const ext = variables.agentResponse?.extractedData || {};
const mustBeYes = ['candidateAge','drivingYears','english','workAuth','smartPhone'];
const failedFields = mustBeYes.filter(f => ext[f] !== 'Yes');
if (ext.candidateSmoke === 'Yes') failedFields.push('candidateSmoke');
const passed = failedFields.length === 0;
const reasonMap = {
  candidateAge: 'Does not meet minimum age requirement',
  drivingYears: 'Does not meet minimum driving experience requirement',
  english: 'Does not meet English fluency requirement',
  workAuth: 'Does not have work authorization',
  smartPhone: 'Does not have a smartphone',
  candidateSmoke: 'Tobacco use disqualifies candidate'
};
const rejectionReason = failedFields.map(f => reasonMap[f] || f).join('; ');
return { passed, rejectionReason: passed ? '' : rejectionReason };

